def naive_search(text, pat):
    comps, hits = 0, []
    for i in range(len(text) - len(pat) + 1):
        j = 0
        while j < len(pat):
            comps += 1
            if text[i + j] != pat[j]:
                break
            j += 1
        if j == len(pat):
            hits.append(i)
    return hits, comps

def kmp_search(text, pat):
    pi = [0] * len(pat)
    for i in range(1, len(pat)):
        j = pi[i - 1]
        while j > 0 and pat[i] != pat[j]:
            j = pi[j - 1]
        if pat[i] == pat[j]:
            j += 1
        pi[i] = j
    comps, hits, j = 0, [], 0
    for i in range(len(text)):
        while True:
            comps += 1
            if text[i] == pat[j]:
                j += 1
                break
            if j == 0:
                break
            j = pi[j - 1]
        if j == len(pat):
            hits.append(i - len(pat) + 1)
            j = pi[j - 1]
    return hits, comps

