def rabin_karp(text, pat, d=10, q=11):
    m, n = len(pat), len(text)
    hpat = 0
    for ch in pat:
        hpat = (d * hpat + int(ch)) % q
    print("pattern", pat, "hashes to", hpat, "mod", q)
    hwin = 0
    for ch in text[:m]:
        hwin = (d * hwin + int(ch)) % q
    for i in range(n - m + 1):
        if i > 0:
            hwin = (d * (hwin - int(text[i - 1]) * pow(d, m - 1, q)) + int(text[i + m - 1])) % q
        window = text[i:i + m]
        if hwin == hpat:
            verdict = "REAL match" if window == pat else "SPURIOUS hit - same hash, different text"
            print(f"window {window!r} at {i}: hash {hwin} == pattern hash -> {verdict}")
        else:
            print(f"window {window!r} at {i}: hash {hwin} - skipped without comparing")

