def rabin_karp_stats(text, pat, d=10, q=101):
    m, n = len(pat), len(text)
    hpat = 0
    for ch in pat:
        hpat = (d * hpat + int(ch)) % q
    hwin = 0
    for ch in text[:m]:
        hwin = (d * hwin + int(ch)) % q
    hits = verified = char_comps = 0
    matches = []
    for i in range(n - m + 1):
        if i > 0:
            hwin = (d * (hwin - int(text[i - 1]) * pow(d, m - 1, q)) + int(text[i + m - 1])) % q
        if hwin == hpat:
            hits += 1
            for a, b in zip(text[i:i + m], pat):
                char_comps += 1
                if a != b:
                    break
            else:
                verified += 1
                matches.append(i)
    return n - m + 1, hits, verified, char_comps, matches

