def lev_full_count(a, b):
    cells = 0
    rows = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(len(a) + 1):
        rows[i][0] = i
    for j in range(len(b) + 1):
        rows[0][j] = j
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            cells += 1
            cost = 0 if a[i - 1] == b[j - 1] else 1
            rows[i][j] = min(rows[i - 1][j] + 1, rows[i][j - 1] + 1, rows[i - 1][j - 1] + cost)
    return rows[-1][-1], cells

def lev_banded_count(a, b, k):
    if abs(len(a) - len(b)) > k:
        return None, 0
    cells = 0
    INF = float("inf")
    prev = {j: j for j in range(0, min(len(b), k) + 1)}
    for i in range(1, len(a) + 1):
        lo, hi = max(0, i - k), min(len(b), i + k)
        cur = {}
        for j in range(lo, hi + 1):
            cells += 1
            if j == 0:
                cur[j] = i
                continue
            cost = 0 if a[i - 1] == b[j - 1] else 1
            cur[j] = min(prev.get(j, INF) + 1, cur.get(j - 1, INF) + 1, prev.get(j - 1, INF) + cost)
        prev = cur
    d = prev.get(len(b), INF)
    return (d if d <= k else None), cells

