def jaro(s, t):
    if s == t:
        return 1.0
    ls, lt = len(s), len(t)
    if not ls or not lt:
        return 0.0
    dist = max(ls, lt) // 2 - 1
    s_match = [False] * ls
    t_match = [False] * lt
    matches = 0
    for i in range(ls):
        lo, hi = max(0, i - dist), min(i + dist + 1, lt)
        for j in range(lo, hi):
            if not t_match[j] and s[i] == t[j]:
                s_match[i] = t_match[j] = True
                matches += 1
                break
    if not matches:
        return 0.0
    k, trans = 0, 0
    for i in range(ls):
        if s_match[i]:
            while not t_match[k]:
                k += 1
            if s[i] != t[k]:
                trans += 1
            k += 1
    return (matches / ls + matches / lt + (matches - trans // 2) / matches) / 3

def jaro_winkler(s, t, p=0.1):
    j = jaro(s, t)
    prefix = 0
    for x, y in zip(s, t):
        if x == y and prefix < 4:
            prefix += 1
        else:
            break
    return j + prefix * p * (1 - j)

