def longest_repeated(s):
    best = ""
    seen = {}
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            sub = s[i:j]
            if len(sub) <= len(best):
                continue
            if sub in seen and seen[sub] != i:
                best = sub
            seen.setdefault(sub, i)
    return best

