def dice_bigram(a, b):
    A = {a[i:i + 2] for i in range(len(a) - 1)}
    B = {b[i:i + 2] for i in range(len(b) - 1)}
    return 2 * len(A & B) / (len(A) + len(B))

def jaro(s, t):
    if s == t:
        return 1.0
    ls, lt = len(s), len(t)
    dist = max(ls, lt) // 2 - 1
    sm, tm = [False] * ls, [False] * lt
    m = 0
    for i in range(ls):
        for j in range(max(0, i - dist), min(i + dist + 1, lt)):
            if not tm[j] and s[i] == t[j]:
                sm[i] = tm[j] = True
                m += 1
                break
    if not m:
        return 0.0
    k = trans = 0
    for i in range(ls):
        if sm[i]:
            while not tm[k]:
                k += 1
            if s[i] != t[k]:
                trans += 1
            k += 1
    return (m / ls + m / lt + (m - trans // 2) / m) / 3

