def parse_duration(s):
    if not s:
        raise ValueError("empty duration")
    total, i = 0, 0
    seen = set()
    while i < len(s):
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1
        if j == i:
            raise ValueError(f"expected a number at index {i} in {s!r}")
        if j >= len(s) or s[j] not in UNITS:
            raise ValueError(f"expected a unit (d/h/m/s) at index {j} in {s!r}")
        unit = s[j]
        if unit in seen:
            raise ValueError(f"unit {unit!r} repeated in {s!r}")
        seen.add(unit)
        total += int(s[i:j]) * UNITS[unit]
        i = j + 1
    return total

