            i += 2
        else:
            j = i + 1
            while j < len(template) and (template[j].isalnum() or template[j] == "_"):
                j += 1
            name = template[i + 1:j]
            if not name:
                raise ValueError(f"dangling '$' at index {i}")
            if name not in values:
                raise KeyError(f"no value for placeholder {name!r}")
            out.append(str(values[name]))
            i = j
    return "".join(out)

