def jaro(s, t):
    if s == t:
        return 1.0
    ls, lt = len(s), len(t)
    dist = max(ls, lt) // 2 - 1
    sm, tm = [False] * ls, [False] * lt
    m = 0
    for i in range(ls):
        for j in range(max(0, i - dist), min(i + dist + 1, lt)):
            if not tm[j] and s[i] == t[j]:
                sm[i] = tm[j] = True
                m += 1
                break
    if not m:
        return 0.0
    k = trans = 0
    for i in range(ls):
        if sm[i]:
            while not tm[k]:
                k += 1
            if s[i] != t[k]:
                trans += 1
            k += 1
    j = (m / ls + m / lt + (m - trans // 2) / m) / 3
    prefix = 0
    for x, y in zip(s, t):
        if x == y and prefix < 4:
            prefix += 1
        else:
            break
    return j + prefix * 0.1 * (1 - j)

