def approx_search(text, pat, k):
    hits = []
    for i in range(len(text) - len(pat) + 1):
        mismatches = sum(1 for a, b in zip(text[i:i + len(pat)], pat) if a != b)
        if mismatches <= k:
            hits.append((i, mismatches))
    return hits

