def approx_count(text, pat, k):
    hits = []
    for i in range(len(text) - len(pat) + 1):
        m = sum(1 for a, b in zip(text[i:i + len(pat)], pat) if a != b)
        if m <= k:
            hits.append(i)
    return hits

