def naive_search(text, pat):
    comps = 0
    for i in range(len(text) - len(pat) + 1):
        j = 0
        while j < len(pat):
            comps += 1
            if text[i + j] != pat[j]:
                break
            j += 1
        if j == len(pat):
            return comps
    return comps

def build_pi(pat):
    pi = [0] * len(pat)
    comps = 0
    for i in range(1, len(pat)):
        j = pi[i - 1]
        while j > 0 and pat[i] != pat[j]:
            comps += 1
            j = pi[j - 1]
        comps += 1
        if pat[i] == pat[j]:
            j += 1
        pi[i] = j
    return pi, comps

def kmp_search(text, pat, pi):
    comps, j = 0, 0
    for i in range(len(text)):
        while True:
            comps += 1
            if text[i] == pat[j]:
                j += 1
                break
            if j == 0:
                break
            j = pi[j - 1]
        if j == len(pat):
            return comps
    return comps

